 bindCommon();enhance();bindCourseSelector();const toggle=document.querySelector('#openWorkspace'),sidebar=document.querySelector('#workspaceSidebar'),backdrop=document.querySelector('#workspaceBackdrop'),main=document.querySelector('.workspace-main');const mobile=()=>matchMedia('(max-width: 980px)').matches;
