 const capture=captureEditor=()=>{const form=document.querySelector('#editorForm');for(const [path,value]of new FormData(form)){if(path==='action'||path.startsWith('flag'))continue;const keys=path.split('.');let ref=m;for(const part of keys.slice(0,-1))ref=ref[part];ref[keys.at(-1)]=path==='time'||path==='practice.correct'||/^q\.\d\.2$/.test(path)?Number(value):String(value).trim()}m.lab[3]=[0,1,2].filter(j=>form.querySelector('[name=flag'+j+']').checked)};
