 document.querySelector('#editorForm').onsubmit=async e=>{e.preventDefault();capture();const submission=clone(draft),status=document.querySelector('#editorStatus'),publish=e.submitter?.value==='publish';try{if(publish)validateCatalog(submission);if(publish&&!confirm(t('Publier cette version française et anglaise pour tous les participants ? Vérifiez les deux langues avant de confirmer.','Publish this French and English version for all learners? Check both languages before confirming.')))return;const s=session;if(!s||!admin)throw Error(t('Connexion administrateur requise.','Administrator connection required.'));e.submitter.disabled=true;if(publish){const next=await s.f.runTransaction(s.db,async tx=>{const ref=s.f.doc(s.db,...platform.paths(s.uid,scopeCourse).content),current=await tx.get(ref),remoteVersion=current.exists()?current.data().version:1;if(session!==s||!admin||scopeCourse!==platform.current())throw Error('session-changed');if(remoteVersion!==editorVersion)throw Error(t('Une autre version a été publiée. Rechargez les contenus avant de publier. Votre brouillon est conservé en mémoire.','Another version was published. Reload the content before publishing. Your draft remains in memory.'));const archiveRef=s.f.doc(s.db,...platform.paths(s.uid,scopeCourse).versions,String(remoteVersion)),archived=await tx.get(archiveRef);if(session!==s||!admin||scopeCourse!==platform.current())throw Error('session-changed');if(!archived.exists())tx.set(archiveRef,{fr:current.exists()?current.data().fr:catalog.fr,en:current.exists()?current.data().en:catalog.en,version:remoteVersion,publishedAt:s.f.serverTimestamp()});const version=remoteVersion+1,payload={fr:submission.fr,en:submission.en,version,publishedAt:s.f.serverTimestamp()};tx.set(ref,payload);tx.set(s.f.doc(s.db,...platform.paths(s.uid,scopeCourse).versions,String(version)),payload);return version});if(session!==s||!admin||scopeCourse!==platform.current())throw Error('session-changed');catalog={fr:clone(submission.fr),en:clone(submission.en),version:next};contentCache.set(scopeCourse,clone(catalog));draft.version=next;editorVersion=next;applyLanguage();status.textContent=t('Version publiée : ','Published version: ')+next;}else{await s.f.setDoc(s.f.doc(s.db,...platform.paths(s.uid,scopeCourse).draft),{fr:submission.fr,en:submission.en,version:editorVersion,updatedAt:s.f.serverTimestamp()});if(session!==s||!admin||scopeCourse!==platform.current())return;status.textContent=t('Brouillon enregistré. Rien n’a été publié.','Draft saved. Nothing was published.')}}catch(error){status.textContent=t('Enregistrement impossible : ','Could not save: ')+(error.code==='permission-denied'?t('vérifiez les règles et votre rôle administrateur.','check security rules and your administrator role.'):error.message)}finally{if(e.submitter)e.submitter.disabled=false}};
 document.querySelector('#loadDraft').onclick=async()=>{if(!confirm(t('Remplacer les modifications de cet atelier par le brouillon enregistré ?','Replace this editor’s changes with the saved draft?')))return;try{const s=session;if(!s||!admin)throw Error('session-changed');const snap=await s.f.getDoc(s.f.doc(s.db,...platform.paths(s.uid,scopeCourse).draft));if(session!==s||!admin||scopeCourse!==platform.current())return;if(!snap.exists())throw Error(t('Aucun brouillon enregistré.','No saved draft.'));const saved=snap.data();if(!Array.isArray(saved.fr)||!Array.isArray(saved.en))throw Error('Invalid draft');draft=saved;adminPage()}catch(e){notify(e.message)}};
 document.querySelector('#loadVersions').onclick=async()=>{try{const s=session,res=await s.f.getDocs(s.f.query(s.f.collection(s.db,...platform.paths(s.uid,scopeCourse).versions),s.f.orderBy('version','desc'),s.f.limit(10)));const box=document.querySelector('#versionList');box.innerHTML=res.empty?`<p>${t('Aucune version publiée depuis cet atelier.','No versions published from this studio yet.')}</p>`:res.docs.map(d=>`<p>Version ${d.data().version} <button class="link-btn" data-restore="${safe(d.id)}">${t('Reprendre en brouillon','Use as draft')}</button></p>`).join('');box.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{if(!confirm(t('Charger cette ancienne version dans le brouillon ? Elle ne sera pas publiée automatiquement.','Load this version as a draft? It will not be published automatically.')))return;const old=res.docs.find(d=>d.id===b.dataset.restore).data();draft=validateCatalog({...old,version:catalog.version});adminPage()})}catch{notify(t('Impossible de charger les versions. Vérifiez vos droits.','Could not load versions. Check your permissions.'))}};
 document.querySelector('#loadFeedback').onclick=async()=>{try{const s=session,res=await s.f.getDocs(s.f.query(s.f.collection(s.db,...platform.paths(s.uid,scopeCourse).feedbackCollection),s.f.orderBy('updatedAt','desc'),s.f.limit(50)));document.querySelector('#feedbackList').innerHTML=res.empty?`<p>${t('Aucun avis reçu.','No feedback received.')}</p>`:res.docs.map(doc=>{const d=doc.data();return `<article class="feedback-entry"><b>${Number(d.rating)} / 5</b> · ${safe(d.prepared)}<p>${safe(d.comment)}</p><span class="small">${d.updatedAt?.toDate?date(d.updatedAt.toDate()):''}</span></article>`}).join('')}catch{notify(t('Avis inaccessibles. Publiez les nouvelles règles et vérifiez le rôle administrateur.','Feedback is unavailable. Publish the new rules and check the administrator role.'))}};
