 const platform=window.CyberPlatform,contentCache=new Map();let catalogLoads=new Set(),roleUnsubscribe=null,captureEditor=null,feedbackView=0;
 function scopeData(){const id=platform.current();if(id===platform.primary)return data;data.courses??={};return data.courses[id]??(data.courses[id]={events:{},assessments:{},exercises:{}})}
 function activate(id,uid){if(captureEditor&&document.querySelector('#editorForm'))captureEditor();platform.select(id,uid);const entry=platform.get(id);catalog=contentCache.get(id)||{fr:clone(entry.fr),en:clone(entry.en),version:1};draft=null;editIndex=0;editorDirty=false;applyLanguage();if(typeof authAPI!=='undefined'&&authAPI?.auth?.app)loadCatalog(authAPI.auth.app)}
 function activateForUser(uid){const entry=uid?platform.forUser(uid):platform.select(platform.primary);activate(entry.id,uid)}
 function accessScreen(path){const result=platform.access(path,{ready:authReady,signedIn:!!user,isAdmin:admin,roleReady:adminChecked});if(result==='pending'){infoPage(t('Un instant…','One moment…'),`<p role="status">${t('Nous préparons votre espace.','Preparing your space.')}</p>`);return false}if(result==='login'){try{sessionStorage.setItem('cyberilo-return',path)}catch{}location.replace('#/compte');signInPage();return false}if(result==='forbidden'){shell(t('Accès réservé','Restricted access'),`<section class="panel empty-state"><h2>${t('Cet espace est réservé aux administrateurs.','This area is for administrators.')}</h2><a class="btn light" href="#/espace">${t('Revenir à mon espace','Back to my learning')}</a></section>`);return false}return true}
 function afterLogin(){let path='/espace';try{const next=sessionStorage.getItem('cyberilo-return');sessionStorage.removeItem('cyberilo-return');if(next&&/^\/[a-z0-9/-]+$/.test(next)&&platform.protectedRoute(next))path=next}catch{}return path}
 function cachedProgress(id){if(id===platform.current())return state;try{const raw=localStorage.getItem(platform.progressKey(user?.uid,id));return raw?normalize(JSON.parse(raw)):blank()}catch{return blank()}}
 function trainingLabel(id=platform.current()){return platform.get(id)?.title?.[lang]||t('Formation','Course')}
 function catalogCards(personal=false){const list=platform.courses();return `<div class="training-grid">${list.map(c=>{const modules=contentCache.get(c.id)?.fr||c.fr,progress=user?cachedProgress(c.id):blank(),count=Math.min(progress.completed.length,modules.length),started=count>0||Object.keys(progress.lessonSteps).length>0;return `<article class="training-card"><div class="training-cover">${icon('shield')}<span>${safe(c.category?.[lang]||t('Sécurité numérique','Digital security'))}</span></div><div class="training-card-body"><div class="row"><span class="soft-badge">${safe(c.level?.[lang]||t('Débutant','Beginner'))}</span><span class="small">${modules.length} modules · ≈ ${modules.reduce((n,m)=>n+m.time,0)} min</span></div><h2>${safe(c.title[lang])}</h2><p>${safe(c.description[lang])}</p>${personal&&started?`<div class="track" role="progressbar" aria-label="${t('Progression de cette formation','Course progress')}" aria-valuemin="0" aria-valuemax="${modules.length}" aria-valuenow="${count}"><span style="width:${count/modules.length*100}%"></span></div><p class="small">${count} / ${modules.length} ${t('modules validés','modules completed')}</p>`:''}<a class="btn ${personal&&started?'':'light'}" href="#/formation/${c.id}">${personal&&started?t('Retrouver ma formation','Return to my course'):t('Découvrir la formation','Explore this course')} →</a></div></article>`}).join('')}</div>`}
 function catalogPage(personal=false){if(personal&&!gate())return;shell(personal?t('Mes formations','My courses'):t('Le catalogue Cyberilo','Cyberilo course catalogue'),`<p class="workspace-intro">${personal?t('Choisissez la formation à reprendre. Chaque parcours garde ses propres acquis.','Choose a course to continue. Each course keeps its own progress.'):t('Des formations concrètes pour mieux protéger votre vie numérique.','Practical courses to help protect your digital life.')}</p>${catalogCards(personal)}<p class="small">${t('Seules les formations disponibles sont affichées. Le catalogue s’enrichira progressivement.','Only available courses are shown. More courses will be added over time.')}</p>`)}
 async function openTraining(id,go=false){const entry=platform.get(id);if(!entry||!platform.courses().some(c=>c.id===id)){notFound();return}if(!user){try{sessionStorage.setItem('cyberilo-return','/formation/'+id)}catch{}location.replace('#/compte');return}const uid=user.uid;if(id!==platform.current()){await window.CyberCourseRuntime.select(id);if(user?.uid!==uid)return}if(go)location.hash='/module/'+Math.min(state.current,COURSE.length-1);else location.hash='/formation/'+id;render()}
 function trainingDetail(id){if(!gate())return;const entry=platform.get(id);if(!entry||!platform.courses().some(c=>c.id===id)){notFound();return}const selected=id===platform.current(),progress=cachedProgress(id),modules=selected?COURSE:entry[lang];shell(safe(entry.title[lang]),`<p class="workspace-intro">${safe(entry.description[lang])}</p><section class="panel training-intro"><div><span class="soft-badge">${t('Gratuit','Free')}</span><span class="soft-badge">${safe(entry.level?.[lang]||t('Débutant','Beginner'))}</span><h2>${t('Un parcours, un réflexe à la fois.','One course, one good habit at a time.')}</h2><p>${modules.length} modules · ≈ ${modules.reduce((sum,m)=>sum+m.time,0)} min · FR / EN</p><p>${t('Votre progression et vos résultats appartiennent à cette formation. Les modules se débloquent dans l’ordre.','Progress and results belong to this course. Modules unlock in order.')}</p></div><button class="btn" id="openTraining">${progress.completed.length||Object.keys(progress.lessonSteps).length?t('Reprendre cette formation','Continue this course'):t('Commencer cette formation','Start this course')} →</button></section><section class="panel"><h2>${t('Le programme','Course outline')}</h2><div class="course-roadmap">${modules.map((m,i)=>`<div class="roadmap-row"><span class="roadmap-number ${progress.completed.includes(i)?'done':''}">${progress.completed.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><span><b>${safe(m.title)}</b><small>${safe(m.desc)}</small></span><span class="roadmap-state">${m.time} min</span></div>`).join('')}</div></section>`);document.querySelector('#openTraining').onclick=async e=>{e.currentTarget.disabled=true;await openTraining(id,true)}}
 function courseSelector(){if(!user)return '';return `<label class="course-context"><span>${t('Formation sélectionnée','Selected course')}</span><select data-course-select aria-label="${t('Choisir une formation','Choose a course')}">${platform.courses().map(c=>`<option value="${c.id}" ${c.id===platform.current()?'selected':''}>${safe(c.title[lang])}</option>`).join('')}</select></label>`}
